//! On-disk data: the inventory (regenerated by `scan`) and the map (written
//! by claims, links and notes, meant to be committed).

use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

pub const DIR: &str = ".seam";
const INVENTORY: &str = "inventory.json";
const MAP: &str = "map.json";

#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum NodeKind {
    Function,
    Method,
    File,
}

/// One reviewable unit of code: a function, a method, or a whole file.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Node {
    /// Stable across scans: `path#Qualified.name`, or just `path` for files.
    pub id: String,
    pub kind: NodeKind,
    pub name: String,
    pub path: String,
    pub lang: String,
    pub start_line: usize,
    pub end_line: usize,
    /// Hash of the node's source, used to notice when reviewed code changes.
    pub hash: String,
    /// False for file nodes whose code all lives inside functions.
    pub reviewable: bool,
    pub is_test: bool,
    /// Names called from inside this node, as written in the source.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub calls: Vec<String>,
    /// Functions named here without being called: decorators, handlers
    /// passed to a router, callbacks.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub mentions: Vec<String>,
    /// File nodes only: words from the file's import lines. A call into
    /// another file is only believed when that file is imported here.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub imports: Vec<String>,
}

/// Enough to tell whether a file changed since it was last parsed.
#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq)]
pub struct Stamp {
    pub modified: u64,
    pub size: u64,
}

pub const INVENTORY_VERSION: u32 = 7;

#[derive(Serialize, Deserialize, Default, Debug)]
pub struct Inventory {
    pub version: u32,
    pub nodes: Vec<Node>,
    /// Every scanned file, so the next scan only parses what changed.
    #[serde(default)]
    pub files: BTreeMap<String, Stamp>,
    /// Hash of every function name. Mentions depend on the full set, so they
    /// are recomputed everywhere when it changes.
    #[serde(default)]
    pub names: String,
}

#[derive(Serialize, Deserialize, Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[serde(rename_all = "lowercase")]
pub enum ClaimKind {
    /// Untrusted input enters here.
    Entry,
    /// A check that gates access or validates input.
    Guard,
    /// A sensitive operation.
    Sink,
    /// Sensitive data is defined or stored here.
    Data,
    /// Reviewed, nothing security-relevant.
    None,
}

impl ClaimKind {
    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "entry" => Some(Self::Entry),
            "guard" => Some(Self::Guard),
            "sink" => Some(Self::Sink),
            "data" => Some(Self::Data),
            "none" => Some(Self::None),
            _ => None,
        }
    }

    pub fn as_str(self) -> &'static str {
        match self {
            Self::Entry => "entry",
            Self::Guard => "guard",
            Self::Sink => "sink",
            Self::Data => "data",
            Self::None => "none",
        }
    }
}

/// A statement about a node, backed by a quote that was found in its source.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Claim {
    pub node: String,
    pub kind: ClaimKind,
    /// What the node does, in one line.
    pub summary: String,
    /// Exact code the claim rests on. Empty only for `none`.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub quote: String,
    /// Line the quote was found on when the claim was accepted.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub line: Option<usize>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tags: Vec<String>,
    /// Node hash at the time of the claim.
    pub hash: String,
}

/// An asserted flow from one node to another, backed by a quote in `from`.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Link {
    pub from: String,
    pub to: String,
    pub why: String,
    pub quote: String,
    pub line: usize,
}

/// An inferred connection that someone checked and found to be wrong.
#[derive(Serialize, Deserialize, Clone, Debug, PartialEq, Eq)]
pub struct Cut {
    pub from: String,
    pub to: String,
}

#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct Note {
    pub node: String,
    /// idea, tested, dead-end or finding.
    pub status: String,
    pub text: String,
}

#[derive(Serialize, Deserialize, Default, Debug)]
pub struct Map {
    pub version: u32,
    #[serde(default)]
    pub claims: Vec<Claim>,
    #[serde(default)]
    pub links: Vec<Link>,
    #[serde(default)]
    pub notes: Vec<Note>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub cuts: Vec<Cut>,
}

/// Finds the project root: the nearest ancestor that already has `.seam`.
pub fn find_root(start: &Path) -> Option<PathBuf> {
    let mut dir = Some(start);
    while let Some(d) = dir {
        if d.join(DIR).is_dir() {
            return Some(d.to_path_buf());
        }
        dir = d.parent();
    }
    None
}

/// The last inventory, if there is one this version can reuse.
pub fn load_inventory(root: &Path) -> Option<Inventory> {
    let text = fs::read_to_string(root.join(DIR).join(INVENTORY)).ok()?;
    let inv: Inventory = serde_json::from_str(&text).ok()?;
    (inv.version == INVENTORY_VERSION).then_some(inv)
}

pub fn save_inventory(root: &Path, inv: &Inventory) -> Result<()> {
    let dir = root.join(DIR);
    fs::create_dir_all(&dir)?;
    // The inventory is derived from the code, so it stays out of git.
    let ignore = dir.join(".gitignore");
    if !ignore.exists() {
        fs::write(&ignore, "inventory.json\nview.html\nlock\n*.tmp\n")?;
    }
    fs::write(dir.join(INVENTORY), serde_json::to_string(inv)?)?;
    Ok(())
}

pub fn load_map(root: &Path) -> Result<Map> {
    let path = root.join(DIR).join(MAP);
    if !path.exists() {
        return Ok(Map {
            version: 1,
            ..Default::default()
        });
    }
    Ok(serde_json::from_str(&fs::read_to_string(&path)?)?)
}

pub fn save_map(root: &Path, map: &Map) -> Result<()> {
    let mut map = Map {
        version: 1,
        claims: map.claims.clone(),
        links: map.links.clone(),
        notes: map.notes.clone(),
        cuts: map.cuts.clone(),
    };
    // Sorted so the file diffs cleanly between commits.
    map.claims
        .sort_by(|a, b| (&a.node, a.kind, &a.quote).cmp(&(&b.node, b.kind, &b.quote)));
    map.links
        .sort_by(|a, b| (&a.from, &a.to).cmp(&(&b.from, &b.to)));
    fs::create_dir_all(root.join(DIR))?;
    // Written beside the map and renamed over it, so a crash or a second
    // reader never sees half a file.
    let target = root.join(DIR).join(MAP);
    let scratch = root
        .join(DIR)
        .join(format!("{MAP}.{}.tmp", std::process::id()));
    fs::write(&scratch, serde_json::to_string_pretty(&map)? + "\n")?;
    fs::rename(&scratch, &target)?;
    Ok(())
}

/// Held while a command reads the map, changes it and writes it back, so two
/// agents working in the same repo do not overwrite each other's claims.
pub struct Lock(PathBuf);

impl Lock {
    pub fn acquire(root: &Path) -> Result<Self> {
        use std::time::{Duration, Instant};
        const WAIT: Duration = Duration::from_secs(20);
        /// A lock this old was left behind by a process that died.
        const ABANDONED: Duration = Duration::from_secs(60);

        fs::create_dir_all(root.join(DIR))?;
        let path = root.join(DIR).join("lock");
        let started = Instant::now();
        loop {
            match fs::OpenOptions::new()
                .write(true)
                .create_new(true)
                .open(&path)
            {
                Ok(_) => return Ok(Self(path)),
                Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => {
                    let age = fs::metadata(&path)
                        .and_then(|m| m.modified())
                        .ok()
                        .and_then(|t| t.elapsed().ok());
                    if age.is_some_and(|age| age > ABANDONED) {
                        let _ = fs::remove_file(&path);
                        continue;
                    }
                    if started.elapsed() > WAIT {
                        anyhow::bail!(
                            "another seam command has held {} for too long; remove it if nothing is running",
                            path.display()
                        );
                    }
                    std::thread::sleep(Duration::from_millis(40));
                }
                Err(err) => return Err(err.into()),
            }
        }
    }
}

impl Drop for Lock {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.0);
    }
}

/// How a claim holds up against the code as it is now.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ClaimState {
    /// The node is unchanged since the claim.
    Ok,
    /// The node changed but the quoted code is still there.
    Changed,
    /// The quoted code is gone.
    Stale,
    /// The node no longer exists.
    Orphaned,
}

impl ClaimState {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Ok => "ok",
            Self::Changed => "changed",
            Self::Stale => "stale",
            Self::Orphaned => "orphaned",
        }
    }
}

pub fn index(inv: &Inventory) -> BTreeMap<&str, &Node> {
    inv.nodes.iter().map(|n| (n.id.as_str(), n)).collect()
}
